 boolean requested,done;int age,checks;volatile String failure;int[] before,withEffects,handBefore;int handSkin,handChanged;boolean handFrame,handMeasured;
 public AmbientSceneryVisualTest(){MinecraftForge.EVENT_BUS.addListener(this::tick);MinecraftForge.EVENT_BUS.addListener(this::frameStart);MinecraftForge.EVENT_BUS.addListener(this::frameEnd);MinecraftForge.EVENT_BUS.addListener(net.minecraftforge.eventbus.api.EventPriority.NORMAL,this::beforeEffects);MinecraftForge.EVENT_BUS.addListener(this::afterEffects);}
 void beforeEffects(net.minecraftforge.client.event.RenderGuiEvent.Pre e){if(age!=221||handMeasured||handFrame)return;try{handBefore=shot("hand-before-effects");handFrame=true;}catch(Exception error){throw new RuntimeException(error);}}
 void afterEffects(net.minecraftforge.client.event.RenderGuiEvent.Post e){if(!handFrame)return;try{var after=shot("hand-after-effects");for(int y=520;y<650;y++)for(int x=930;x<1130;x++){int a=handBefore[y*1280+x],b=after[y*1280+x],r=a&255,g=a>>8&255,blue=a>>16&255;if(r>140&&g>100&&blue>65&&r>g+8&&g>blue+8){handSkin++;if(a!=b)handChanged++;}}handMeasured=true;handFrame=false;}catch(Exception error){throw new RuntimeException(error);}}
 void check(boolean ok,String text){if(!ok)throw new AssertionError(text);checks++;System.out.println("ATMOSPHERE VISUAL CHECK: "+text);}
