 int[] shot(String name)throws Exception{var mc=Minecraft.getInstance();try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(java.nio.file.Path.of(System.getProperty("atmosphere.output"),name+".png"));int[] out=new int[image.getWidth()*image.getHeight()];for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)out[y*image.getWidth()+x]=image.getPixelRGBA(x,y);return out;}}
 void aircraftCamera(net.minecraft.server.level.ServerPlayer p){var d=(MapDeviceSystem.Device)p.serverLevel().getBlockEntity(new BlockPos(5,73,24));var at=AmbientScenery.aircraftPosition(d.scenery,0,(p.serverLevel().getGameTime()-d.sceneryStart)/20.0).add(5.5,73,24.5);var eye=at.add(16,7,23);var dir=at.subtract(eye);float yaw=(float)Math.toDegrees(Math.atan2(-dir.x,dir.z)),pitch=(float)-Math.toDegrees(Math.atan2(dir.y,Math.sqrt(dir.x*dir.x+dir.z*dir.z)));p.teleportTo(p.serverLevel(),eye.x,eye.y-1.62,eye.z,yaw,pitch);}

 void profileDevices(net.minecraft.server.level.ServerPlayer p,boolean enabled){for(var pos:java.util.List.of(new BlockPos(0,73,24),new BlockPos(5,73,24),new BlockPos(10,73,24))){var d=(MapDeviceSystem.Device)p.serverLevel().getBlockEntity(pos);var n=d.config();n.putBoolean("enabled",enabled);d.configure(n);}}
