 record Gpu(int start,int end,int group,long cpu){}
 java.util.ArrayDeque<Gpu> queries=new java.util.ArrayDeque<>();Gpu frame;
 java.util.Map<Integer,java.util.ArrayList<Double>> gpu=new java.util.HashMap<>(),cpu=new java.util.HashMap<>();
 int profileGroup(){return age>=330&&age<370?1:age>=400&&age<440?2:age>=470&&age<510?3:age>=540&&age<580?4:0;}
 void frameStart(TickEvent.RenderTickEvent event){if(event.phase!=TickEvent.Phase.START||done)return;collectGpu();int group=profileGroup();if(group==0||queries.size()>7||frame!=null)return;int start=org.lwjgl.opengl.GL15.glGenQueries(),end=org.lwjgl.opengl.GL15.glGenQueries();frame=new Gpu(start,end,group,System.nanoTime());org.lwjgl.opengl.GL33.glQueryCounter(start,org.lwjgl.opengl.GL33.GL_TIMESTAMP);}
 void frameEnd(net.minecraftforge.client.event.RenderGuiEvent.Pre e){if(frame==null)return;org.lwjgl.opengl.GL33.glQueryCounter(frame.end,org.lwjgl.opengl.GL33.GL_TIMESTAMP);cpu.computeIfAbsent(frame.group,k->new java.util.ArrayList<>()).add((System.nanoTime()-frame.cpu)/1e6);queries.add(frame);frame=null;}
 void collectGpu(){while(!queries.isEmpty()&&org.lwjgl.opengl.GL15.glGetQueryObjecti(queries.peek().end,org.lwjgl.opengl.GL15.GL_QUERY_RESULT_AVAILABLE)!=0){var q=queries.remove();double ms=(org.lwjgl.opengl.GL33.glGetQueryObjectui64(q.end,org.lwjgl.opengl.GL15.GL_QUERY_RESULT)-org.lwjgl.opengl.GL33.glGetQueryObjectui64(q.start,org.lwjgl.opengl.GL15.GL_QUERY_RESULT))/1e6;gpu.computeIfAbsent(q.group,k->new java.util.ArrayList<>()).add(ms);org.lwjgl.opengl.GL15.glDeleteQueries(q.start);org.lwjgl.opengl.GL15.glDeleteQueries(q.end);}}
 void reportGpu(){collectGpu();for(int group=1;group<=4;group++){var rows=gpu.getOrDefault(group,new java.util.ArrayList<>());rows.sort(Double::compare);var cpus=cpu.getOrDefault(group,new java.util.ArrayList<>());cpus.sort(Double::compare);check(rows.size()>5,"GPU timing collected for scenery benchmark group "+group);System.out.println("SCENERY GPU "+new String[]{"","baseline","devices","nuclear-sky","combined"}[group]+" samples="+rows.size()+" median_ms="+rows.get(rows.size()/2)+" p95_ms="+rows.get(Math.min(rows.size()-1,(int)(rows.size()*.95)))+" cpu_ms="+cpus.get(cpus.size()/2));}}
